                <div className="text-right">
                  <span className="block text-sm font-medium text-gray-900">{edu.year}</span>
                  <span className="block text-xs text-gray-500">{edu.location}</span>
                </div>
              </div>
            ))}
          </div>
        </section>

      </div>
    </div>
  );
