import { Sparkles, AlertCircle, LogOut, User as UserIcon } from 'lucide-react';

const initialInput: UserInput = {
  fullName: '',
  email: '',
  phone: '',
  linkedin: '',
  github: '',
  website: '',
  jobTitle: '',
  experienceLevel: 'Mid Level',
  skills: '',
  experience: '',
  education: [],
  projects: '',
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [appState, setAppState] = useState<AppState>(AppState.EDITING);
  const [inputData, setInputData] = useState<UserInput>(initialInput);
  const [resumeData, setResumeData] = useState<GeneratedResume | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isGuest, setIsGuest] = useState(false);

  const handleLogin = (identifier: string, type: 'email' | 'phone') => {
    setIsAuthenticated(true);
    setIsGuest(false);
    // Pre-fill data based on login
    setInputData(prev => ({
      ...prev,
      [type]: identifier
    }));
  };

  const handleGuestLogin = () => {
    setIsAuthenticated(true);
    setIsGuest(true);
    setInputData(initialInput);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsGuest(false);
    setAppState(AppState.EDITING);
    setInputData(initialInput);
    setResumeData(null);
    setError(null);
  };

  const handleGenerate = async () => {
    setAppState(AppState.GENERATING);
    setError(null);
    try {
      const result = await generateResumeContent(inputData);
      setResumeData(result);
      setAppState(AppState.VIEWING);
    } catch (err) {
      console.error(err);
      setError("Failed to generate resume. Please ensure all fields contain valid information and try again.");
      setAppState(AppState.EDITING);
    }
  };

  const handleEdit = () => {
    setAppState(AppState.EDITING);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} onGuestLogin={handleGuestLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-100 print:bg-white">
      {/* Navbar - hidden on print */}
      <nav className="no-print bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <Sparkles className="h-8 w-8 text-sky-600" />
              <span className="ml-2 text-xl font-bold text-gray-900 tracking-tight">Resume Architect</span>
            </div>
            <div className="flex items-center gap-4">
               {isGuest ? (
                 <span className="text-sm text-gray-500 flex items-center gap-1 bg-gray-100 px-3 py-1 rounded-full">
                   <UserIcon className="w-4 h-4" /> Guest
                 </span>
               ) : (
                 <span className="text-sm text-sky-700 font-medium hidden sm:block">
                   {inputData.email || inputData.phone}
                 </span>
               )}
               <button 
                 onClick={handleLogout}
                 className="flex items-center gap-2 text-sm text-gray-600 hover:text-red-600 transition-colors font-medium"
               >
                 <LogOut className="w-4 h-4" />
                 <span className="hidden sm:inline">Logout</span>
               </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 print:p-0 print:max-w-none">

        {error && (
          <div className="no-print mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3 text-red-700">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div>
              <h4 className="font-semibold">Error</h4>
              <p className="text-sm">{error}</p>
            </div>
          </div>
        )}

        {appState === AppState.EDITING || appState === AppState.GENERATING ? (
          <div className="max-w-3xl mx-auto animate-in fade-in duration-500">
            <div className="mb-6 text-center">
              <h1 className="text-3xl font-extrabold text-gray-900 sm:text-4xl">
                Build your perfect resume
              </h1>
              <p className="mt-3 text-lg text-gray-500">
                Enter your messy notes, and let AI structure them into a professional, ATS-optimized document.
              </p>
            </div>
            <ResumeForm 
              input={inputData} 
              setInput={setInputData} 
              onGenerate={handleGenerate}
              isGenerating={appState === AppState.GENERATING}
            />
          </div>
        ) : (
          resumeData && (
            <div className="animate-in slide-in-from-bottom-4 duration-700">
              <ResumePreview 
                data={resumeData} 
                personalInfo={inputData} 
                onEdit={handleEdit} 
              />
            </div>
          )
        )}
      </main>

      {/* Footer */}
      <footer className="no-print bg-white border-t border-gray-200 mt-12 py-8">
        <div className="max-w-5xl mx-auto px-4 text-center text-gray-400 text-sm">
          <p>© {new Date().getFullYear()} Resume Architect.</p>
          <p className="text-[10px] mt-2 opacity-60">Developed by Tanzim</p>
        </div>
      </footer>
    </div>
  );
}

export default App;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { UserInput, GeneratedResume } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const resumeSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    professionalSummary: {
      type: Type.STRING,
      description: "A compelling 3-4 line professional summary optimized for ATS.",
    },
    workExperience: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          role: { type: Type.STRING },
          company: { type: Type.STRING },
          location: { type: Type.STRING },
          duration: { type: Type.STRING },
          points: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Action-oriented bullet points using strong verbs.",
          },
        },
        required: ["role", "company", "duration", "points"],
      },
    },
    skills: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, description: "e.g., Technical, Soft Skills, Tools" },
          items: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["category", "items"],
      },
    },
    education: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          degree: { type: Type.STRING },
          institution: { type: Type.STRING },
          location: { type: Type.STRING },
          year: { type: Type.STRING },
          details: { type: Type.STRING },
        },
        required: ["degree", "institution", "year"],
      },
    },
    projects: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          description: { type: Type.STRING },
          technologies: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "description"],
      },
    },
  },
  required: ["professionalSummary", "workExperience", "skills", "education"],
};

export const generateResumeContent = async (input: UserInput): Promise<GeneratedResume> => {
  const educationString = input.education
    .map(e => `${e.degree} from ${e.school} (Year: ${e.year})`)
    .join('; ');

  const prompt = `
    You are a professional resume writer and HR expert.
    Create a modern, ATS-friendly resume based on the information provided below.

    Rules:
    - Use clear, professional English
    - Avoid unnecessary words
    - Optimize for Applicant Tracking Systems (ATS)
    - Use strong action verbs (e.g., Spearheaded, Orchestrated, Developed)
    - Do not fabricate fake experience, but polish the existing input to sound professional.
    - Make it suitable for international job markets.

    Input Data:
    Full Name: ${input.fullName}
    Job Title: ${input.jobTitle}
    Experience Level: ${input.experienceLevel}
    GitHub: ${input.github}
    Portfolio/Website: ${input.website}
    Skills: ${input.skills}
    Work Experience Input: ${input.experience}
    Education Input: ${educationString}
    Projects Input: ${input.projects}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: resumeSchema,
        temperature: 0.4, // Keep it relatively deterministic but creative enough for phrasing
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GeneratedResume;
  } catch (error) {
    console.error("Error generating resume:", error);
    throw error;
  }
};

