export enum AppState {
  EDITING,
  GENERATING,
  VIEWING,
}

import React, { useState } from 'react';
import { UserInput, GeneratedResume, AppState } from './types';
import ResumeForm from './components/ResumeForm';
import ResumePreview from './components/ResumePreview';
import Login from './components/Login';
import { generateResumeContent } from './services/geminiService';
import { Sparkles, AlertCircle, LogOut, User as UserIcon } from 'lucide-react';

const initialInput: UserInput = {
  templateId: 'classic',
  photo: '',
  fullName: '',
  email: '',
  phone: '',
  linkedin: '',
  github: '',
  website: '',
  jobTitle: '',
  experienceLevel: 'Mid Level',
  skills: '',
  experience: '',
  education: [],
  projects: '',
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [appState, setAppState] = useState<AppState>(AppState.EDITING);
  const [inputData, setInputData] = useState<UserInput>(initialInput);
  const [resumeData, setResumeData] = useState<GeneratedResume | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isGuest, setIsGuest] = useState(false);

  const handleLogin = (identifier: string, type: 'email' | 'phone') => {
    setIsAuthenticated(true);
    setIsGuest(false);
    // Pre-fill data based on login
    setInputData(prev => ({
      ...prev,
      [type]: identifier
    }));
  };

  const handleGuestLogin = () => {
    setIsAuthenticated(true);
    setIsGuest(true);
    setInputData(initialInput);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsGuest(false);
    setAppState(AppState.EDITING);
    setInputData(initialInput);
    setResumeData(null);
    setError(null);
  };

  const handleGenerate = async () => {
    setAppState(AppState.GENERATING);
    setError(null);
    try {
      const result = await generateResumeContent(inputData);
      setResumeData(result);
      setAppState(AppState.VIEWING);
    } catch (err) {
      console.error(err);
      setError("Failed to generate resume. Please ensure all fields contain valid information and try again.");
      setAppState(AppState.EDITING);
    }
  };

  const handleEdit = () => {
    setAppState(AppState.EDITING);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} onGuestLogin={handleGuestLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-100 print:bg-white">
      {/* Navbar - hidden on print */}
      <nav className="no-print bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <Sparkles className="h-8 w-8 text-sky-600" />
              <span className="ml-2 text-xl font-bold text-gray-900 tracking-tight">Resume Architect</span>
            </div>
            <div className="flex items-center gap-4">
               {isGuest ? (
                 <span className="text-sm text-gray-500 flex items-center gap-1 bg-gray-100 px-3 py-1 rounded-full">
                   <UserIcon className="w-4 h-4" /> Guest
                 </span>
               ) : (
                 <span className="text-sm text-sky-700 font-medium hidden sm:block">
                   {inputData.email || inputData.phone}
                 </span>
               )}
               <button 
                 onClick={handleLogout}
                 className="flex items-center gap-2 text-sm text-gray-600 hover:text-red-600 transition-colors font-medium"
               >
                 <LogOut className="w-4 h-4" />
                 <span className="hidden sm:inline">Logout</span>
               </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 print:p-0 print:max-w-none">

        {error && (
          <div className="no-print mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3 text-red-700">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div>
              <h4 className="font-semibold">Error</h4>
              <p className="text-sm">{error}</p>
            </div>
          </div>
        )}

        {appState === AppState.EDITING || appState === AppState.GENERATING ? (
          <div className="max-w-3xl mx-auto animate-in fade-in duration-500">
            <div className="mb-6 text-center">
              <h1 className="text-3xl font-extrabold text-gray-900 sm:text-4xl">
                Build your perfect resume
              </h1>
              <p className="mt-3 text-lg text-gray-500">
                Choose a template, enter your details, and let AI structure your professional story.
              </p>
            </div>
            <ResumeForm 
              input={inputData} 
              setInput={setInputData} 
              onGenerate={handleGenerate}
              isGenerating={appState === AppState.GENERATING}
            />
          </div>
        ) : (
          resumeData && (
            <div className="animate-in slide-in-from-bottom-4 duration-700">
              <ResumePreview 
                data={resumeData} 
                personalInfo={inputData} 
                onEdit={handleEdit} 
              />
            </div>
          )
        )}
      </main>

      {/* Footer */}
      <footer className="no-print bg-white border-t border-gray-200 mt-12 py-8">
        <div className="max-w-5xl mx-auto px-4 text-center text-gray-400 text-sm">
          <p>© {new Date().getFullYear()} Resume Architect.</p>
          <p className="text-[10px] mt-2 opacity-60">Developed by Tanzim</p>
        </div>
      </footer>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { UserInput, TemplateId } from '../types';
import { Briefcase, GraduationCap, Code, User, FileText, Github, Globe, Trash2, Plus, Layout, Image as ImageIcon, X } from 'lucide-react';

interface ResumeFormProps {
  input: UserInput;
  setInput: React.Dispatch<React.SetStateAction<UserInput>>;
  onGenerate: () => void;
  isGenerating: boolean;
}

const ResumeForm: React.FC<ResumeFormProps> = ({ input, setInput, onGenerate, isGenerating }) => {
  const [newEdu, setNewEdu] = useState({ degree: '', school: '', year: new Date().getFullYear().toString() });

  const handleChange = (field: keyof UserInput, value: any) => {
    setInput((prev) => ({ ...prev, [field]: value }));
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        handleChange('photo', reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const removePhoto = () => {
    handleChange('photo', '');
  };

  const handleAddEducation = () => {
    if (newEdu.degree.trim() && newEdu.school.trim()) {
      setInput(prev => ({
        ...prev,
        education: [...prev.education, { ...newEdu, id: Date.now().toString() }]
      }));
      setNewEdu({ degree: '', school: '', year: new Date().getFullYear().toString() });
    }
  };

  const handleRemoveEducation = (id: string) => {
    setInput(prev => ({
      ...prev,
      education: prev.education.filter(e => e.id !== id)
    }));
  };

  const inputClasses = "w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-all bg-gray-50 text-gray-900 placeholder-gray-400";
  const textareaClasses = "w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-all resize-y text-sm bg-gray-50 text-gray-900 placeholder-gray-400";

  // Generate years for dropdown
  const currentYear = new Date().getFullYear();
  const years = Array.from({ length: 50 }, (_, i) => (currentYear + 5) - i);

  const templates: { id: TemplateId; name: string; desc: string }[] = [
    { id: 'classic', name: 'Classic ATS', desc: 'Clean, text-focused, best for parsing.' },
    { id: 'modern', name: 'Modern Columns', desc: 'Split layout, sleek and professional.' },
    { id: 'creative', name: '3D Creative', desc: 'Visual profile with photo & depth.' },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="bg-sky-600 p-6 text-white">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <FileText className="w-6 h-6" /> Resume Builder
        </h2>
        <p className="text-sky-50 mt-2">Enter your raw details, and our AI will structure and polish them into a professional resume.</p>
      </div>

      <div className="p-6 space-y-8">

        {/* Template Selection */}
        <section>
          <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
            <Layout className="w-5 h-5 text-sky-500" /> Select Template
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {templates.map((t) => (
              <button
                key={t.id}
                onClick={() => handleChange('templateId', t.id)}
                className={`p-4 rounded-lg border-2 text-left transition-all ${
                  input.templateId === t.id
                    ? 'border-sky-500 bg-sky-50 ring-1 ring-sky-500'
                    : 'border-gray-200 hover:border-sky-200 hover:bg-gray-50'
                }`}
              >
                <div className="font-bold text-gray-900">{t.name}</div>
                <div className="text-xs text-gray-500 mt-1">{t.desc}</div>
                {input.templateId === t.id && (
                  <div className="mt-2 text-xs font-semibold text-sky-600 flex items-center gap-1">
                    <span className="w-2 h-2 rounded-full bg-sky-600"></span> Selected
                  </div>
                )}
              </button>
            ))}
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Personal Info */}
        <section>
          <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
            <User className="w-5 h-5 text-sky-500" /> Personal Details
          </h3>

          <div className="mb-6 bg-gray-50 p-4 rounded-lg border border-gray-200">
             <div className="flex items-center gap-4">
                <div className="h-16 w-16 rounded-full bg-gray-200 overflow-hidden flex items-center justify-center border border-gray-300">
                  {input.photo ? (
                    <img src={input.photo} alt="Profile" className="h-full w-full object-cover" />
                  ) : (
                    <ImageIcon className="w-8 h-8 text-gray-400" />
                  )}
                </div>
                <div className="flex-1">
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Profile Photo {input.templateId === 'creative' ? '(Recommended)' : '(Optional)'}
                  </label>
                  <div className="flex gap-2">
                    <label className="cursor-pointer bg-white border border-gray-300 px-3 py-1.5 rounded text-sm font-medium text-gray-700 hover:bg-gray-50 transition-colors">
                      Upload Image
                      <input type="file" className="hidden" accept="image/*" onChange={handlePhotoUpload} />
                    </label>
                    {input.photo && (
                      <button 
                        onClick={removePhoto}
                        className="text-red-500 hover:text-red-700 text-sm font-medium px-2"
                      >
                        Remove
                      </button>
                    )}
                  </div>
                  <p className="text-xs text-gray-500 mt-1">Recommended for Creative/3D templates</p>
                </div>
             </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Full Name</label>
              <input
                type="text"
                value={input.fullName}
                onChange={(e) => handleChange('fullName', e.target.value)}
                className={inputClasses}
                placeholder="Alex Morgan"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Target Job Title</label>
              <input
                type="text"
                value={input.jobTitle}
                onChange={(e) => handleChange('jobTitle', e.target.value)}
                className={inputClasses}
                placeholder="Senior Software Engineer"
              />
            </div>
             <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Experience Level</label>
              <select
                value={input.experienceLevel}
                onChange={(e) => handleChange('experienceLevel', e.target.value)}
                className={`${inputClasses} appearance-none`}
              >
                <option value="Entry Level">Entry Level (0-2 years)</option>
                <option value="Mid Level">Mid Level (3-5 years)</option>
                <option value="Senior Level">Senior Level (5-10 years)</option>
                <option value="Executive">Executive (10+ years)</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Email</label>
              <input
                type="email"
                value={input.email}
                onChange={(e) => handleChange('email', e.target.value)}
                className={inputClasses}
                placeholder="alex.morgan@example.com"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Phone</label>
              <input
                type="text"
                value={input.phone}
                onChange={(e) => handleChange('phone', e.target.value)}
                className={inputClasses}
                placeholder="+1 234 567 890"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">LinkedIn</label>
              <input
                type="text"
                value={input.linkedin}
                onChange={(e) => handleChange('linkedin', e.target.value)}
                className={inputClasses}
                placeholder="linkedin.com/in/alexmorgan"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700 flex items-center gap-1">
                 <Github className="w-3 h-3" /> GitHub
              </label>
              <input
                type="text"
                value={input.github}
                onChange={(e) => handleChange('github', e.target.value)}
                className={inputClasses}
                placeholder="github.com/alexmorgan"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700 flex items-center gap-1">
                 <Globe className="w-3 h-3" /> Portfolio / Website
              </label>
              <input
                type="text"
                value={input.website}
                onChange={(e) => handleChange('website', e.target.value)}
                className={inputClasses}
                placeholder="alexmorgan.dev"
              />
            </div>
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Experience */}
        <section>
          <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
            <Briefcase className="w-5 h-5 text-sky-500" /> Work Experience
          </h3>
          <div className="space-y-1">
            <label className="text-sm font-medium text-sky-700">Paste your work history (roles, dates, duties)</label>
            <textarea
              value={input.experience}
              onChange={(e) => handleChange('experience', e.target.value)}
              className={`${textareaClasses} h-40`}
              placeholder="e.g. Software Engineer at Google (2020-Present). Built React apps. Improved performance by 20%..."
            />
            <p className="text-xs text-gray-500">Don't worry about formatting. Just dump the text here.</p>
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Skills */}
        <section>
          <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
            <Code className="w-5 h-5 text-sky-500" /> Skills
          </h3>
          <div className="space-y-1">
            <label className="text-sm font-medium text-sky-700">List your skills</label>
            <textarea
              value={input.skills}
              onChange={(e) => handleChange('skills', e.target.value)}
              className={`${textareaClasses} h-24`}
              placeholder="React, TypeScript, Node.js, Leadership, Project Management, Figma..."
            />
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Education & Projects */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <section>
            <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
              <GraduationCap className="w-5 h-5 text-sky-500" /> Education
            </h3>

            <div className="space-y-3">
              {/* Added Education List */}
              {input.education.length > 0 && (
                <div className="space-y-2 mb-4">
                  {input.education.map((edu) => (
                    <div key={edu.id} className="flex justify-between items-center bg-sky-50 p-3 rounded-lg border border-sky-100">
                      <div>
                        <p className="font-semibold text-sm text-sky-900">{edu.degree}</p>
                        <p className="text-xs text-sky-700">{edu.school} • {edu.year}</p>
                      </div>
                      <button 
                        onClick={() => handleRemoveEducation(edu.id)}
                        className="text-red-400 hover:text-red-600 p-1"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              {/* Add Education Form */}
              <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 space-y-3">
                <input 
                  type="text" 
                  value={newEdu.degree}
                  onChange={(e) => setNewEdu(prev => ({ ...prev, degree: e.target.value }))}
                  placeholder="Degree (e.g. B.Sc in CS)"
                  className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-1 focus:ring-sky-500 outline-none bg-gray-50 text-gray-900 placeholder-gray-400"
                />
                <input 
                  type="text" 
                  value={newEdu.school}
                  onChange={(e) => setNewEdu(prev => ({ ...prev, school: e.target.value }))}
                  placeholder="Institution (e.g. Dhaka University)"
                  className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-1 focus:ring-sky-500 outline-none bg-gray-50 text-gray-900 placeholder-gray-400"
                />
                <select
                  value={newEdu.year}
                  onChange={(e) => setNewEdu(prev => ({ ...prev, year: e.target.value }))}
                  className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-1 focus:ring-sky-500 outline-none bg-gray-50 text-gray-900"
                >
                   <option value="Present">Present / Expected</option>
                   {years.map(year => (
                     <option key={year} value={year}>{year}</option>
                   ))}
                </select>
                <button 
                  onClick={handleAddEducation}
                  disabled={!newEdu.degree || !newEdu.school}
                  className="w-full py-2 bg-sky-100 text-sky-700 font-medium rounded hover:bg-sky-200 transition-colors flex items-center justify-center gap-1 text-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Plus className="w-4 h-4" /> Add Education
                </button>
              </div>
            </div>
          </section>

          <section>
            <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
              <Code className="w-5 h-5 text-sky-500" /> Projects (Optional)
            </h3>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">List key projects</label>
              <textarea
                value={input.projects}
                onChange={(e) => handleChange('projects', e.target.value)}
                className={`${textareaClasses} h-[17.5rem]`}
                placeholder="E-commerce website: Built with Next.js and Stripe..."
              />
            </div>
          </section>
        </div>

        <div className="pt-6">
          <button
            onClick={onGenerate}
            disabled={isGenerating || !input.fullName || !input.experience}
            className={`w-full py-4 px-6 rounded-lg text-white font-bold text-lg shadow-lg transform transition-all 
              ${isGenerating || !input.fullName || !input.experience
                ? 'bg-gray-400 cursor-not-allowed' 
                : 'bg-gradient-to-r from-sky-500 to-sky-600 hover:from-sky-600 hover:to-sky-700 hover:-translate-y-0.5'
              } flex items-center justify-center gap-2`}
          >
            {isGenerating ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Drafting your Resume...
              </>
            ) : (
              'Generate Professional Resume'
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

