            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Email</label>
              <input
                type="email"
                value={input.email}
                onChange={(e) => handleChange('email', e.target.value)}
                className={inputClasses}
                placeholder="alex.morgan@example.com"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">Phone</label>
              <input
                type="text"
                value={input.phone}
                onChange={(e) => handleChange('phone', e.target.value)}
                className={inputClasses}
                placeholder="+1 234 567 890"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">LinkedIn</label>
              <input
                type="text"
                value={input.linkedin}
                onChange={(e) => handleChange('linkedin', e.target.value)}
                className={inputClasses}
                placeholder="linkedin.com/in/alexmorgan"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700 flex items-center gap-1">
                 <Github className="w-3 h-3" /> GitHub
              </label>
              <input
                type="text"
                value={input.github}
                onChange={(e) => handleChange('github', e.target.value)}
                className={inputClasses}
                placeholder="github.com/alexmorgan"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700 flex items-center gap-1">
                 <Globe className="w-3 h-3" /> Portfolio / Website
              </label>
              <input
                type="text"
                value={input.website}
                onChange={(e) => handleChange('website', e.target.value)}
                className={inputClasses}
                placeholder="alexmorgan.dev"
              />
            </div>
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Experience */}
        <section>
          <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
            <Briefcase className="w-5 h-5 text-sky-500" /> Work Experience
          </h3>
          <div className="space-y-1">
            <label className="text-sm font-medium text-sky-700">Paste your work history (roles, dates, duties)</label>
            <textarea
              value={input.experience}
              onChange={(e) => handleChange('experience', e.target.value)}
              className={`${textareaClasses} h-40`}
              placeholder="e.g. Software Engineer at Google (2020-Present). Built React apps. Improved performance by 20%..."
            />
            <p className="text-xs text-gray-500">Don't worry about formatting. Just dump the text here.</p>
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Skills */}
        <section>
          <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
            <Code className="w-5 h-5 text-sky-500" /> Skills
          </h3>
          <div className="space-y-1">
            <label className="text-sm font-medium text-sky-700">List your skills</label>
            <textarea
              value={input.skills}
              onChange={(e) => handleChange('skills', e.target.value)}
              className={`${textareaClasses} h-24`}
              placeholder="React, TypeScript, Node.js, Leadership, Project Management, Figma..."
            />
          </div>
        </section>

        <hr className="border-gray-100" />

        {/* Education & Projects */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <section>
            <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
              <GraduationCap className="w-5 h-5 text-sky-500" /> Education
            </h3>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">List your degrees and schools</label>
              <textarea
                value={input.education}
                onChange={(e) => handleChange('education', e.target.value)}
                className={`${textareaClasses} h-32`}
                placeholder="B.Sc in Computer Science, Dhaka University (2018-2022)"
              />
            </div>
          </section>

          <section>
            <h3 className="text-lg font-bold text-sky-700 mb-4 flex items-center gap-2">
              <Code className="w-5 h-5 text-sky-500" /> Projects (Optional)
            </h3>
            <div className="space-y-1">
              <label className="text-sm font-medium text-sky-700">List key projects</label>
              <textarea
                value={input.projects}
                onChange={(e) => handleChange('projects', e.target.value)}
                className={`${textareaClasses} h-32`}
                placeholder="E-commerce website: Built with Next.js and Stripe..."
              />
            </div>
          </section>
        </div>

        <div className="pt-6">
          <button
            onClick={onGenerate}
            disabled={isGenerating || !input.fullName || !input.experience}
            className={`w-full py-4 px-6 rounded-lg text-white font-bold text-lg shadow-lg transform transition-all 
              ${isGenerating || !input.fullName || !input.experience
                ? 'bg-gray-400 cursor-not-allowed' 
                : 'bg-gradient-to-r from-sky-500 to-sky-600 hover:from-sky-600 hover:to-sky-700 hover:-translate-y-0.5'
              } flex items-center justify-center gap-2`}
          >
            {isGenerating ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Drafting your Resume...
              </>
            ) : (
              'Generate Professional Resume'
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ResumeForm;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { UserInput, GeneratedResume } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const resumeSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    professionalSummary: {
      type: Type.STRING,
      description: "A compelling 3-4 line professional summary optimized for ATS.",
    },
    workExperience: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          role: { type: Type.STRING },
          company: { type: Type.STRING },
          location: { type: Type.STRING },
          duration: { type: Type.STRING },
          points: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Action-oriented bullet points using strong verbs.",
          },
        },
        required: ["role", "company", "duration", "points"],
      },
    },
    skills: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, description: "e.g., Technical, Soft Skills, Tools" },
          items: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["category", "items"],
      },
    },
    education: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          degree: { type: Type.STRING },
          institution: { type: Type.STRING },
          location: { type: Type.STRING },
          year: { type: Type.STRING },
          details: { type: Type.STRING },
        },
        required: ["degree", "institution", "year"],
      },
    },
    projects: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          description: { type: Type.STRING },
          technologies: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "description"],
      },
    },
  },
  required: ["professionalSummary", "workExperience", "skills", "education"],
};

export const generateResumeContent = async (input: UserInput): Promise<GeneratedResume> => {
  const prompt = `
    You are a professional resume writer and HR expert.
    Create a modern, ATS-friendly resume based on the information provided below.

    Rules:
    - Use clear, professional English
    - Avoid unnecessary words
    - Optimize for Applicant Tracking Systems (ATS)
    - Use strong action verbs (e.g., Spearheaded, Orchestrated, Developed)
    - Do not fabricate fake experience, but polish the existing input to sound professional.
    - Make it suitable for international job markets.

    Input Data:
    Full Name: ${input.fullName}
    Job Title: ${input.jobTitle}
    Experience Level: ${input.experienceLevel}
    GitHub: ${input.github}
    Portfolio/Website: ${input.website}
    Skills: ${input.skills}
    Work Experience Input: ${input.experience}
    Education Input: ${input.education}
    Projects Input: ${input.projects}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: resumeSchema,
        temperature: 0.4, // Keep it relatively deterministic but creative enough for phrasing
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GeneratedResume;
  } catch (error) {
    console.error("Error generating resume:", error);
    throw error;
  }
};

export type TemplateId = 'classic' | 'modern' | 'creative';

export interface EducationInput {
  id: string;
  degree: string;
  school: string;
  year: string;
}

export interface UserInput {
  templateId: TemplateId;
  photo?: string; // Base64 string for the image
  fullName: string;
  email: string;
  phone: string;
  linkedin: string;
  github: string;
  website: string;
  jobTitle: string;
  experienceLevel: string;
  skills: string;
  experience: string;
  education: EducationInput[];
  projects: string;
}

export interface GeneratedResume {
  professionalSummary: string;
  workExperience: {
    role: string;
    company: string;
    location: string;
    duration: string;
    points: string[];
  }[];
  skills: {
    category: string;
    items: string[];
  }[];
  education: {
    degree: string;
    institution: string;
    location: string;
    year: string;
    details?: string;
  }[];
  projects: {
    name: string;
    description: string;
    technologies: string[];
    link?: string;
  }[];
}

export enum AppState {
  EDITING,
  GENERATING,
  VIEWING,
}

import React, { useState } from 'react';
import { UserInput, GeneratedResume, AppState } from './types';
import ResumeForm from './components/ResumeForm';
import ResumePreview from './components/ResumePreview';
import Login from './components/Login';
import { generateResumeContent } from './services/geminiService';
import { Sparkles, AlertCircle, LogOut, User as UserIcon } from 'lucide-react';

const initialInput: UserInput = {
  templateId: 'classic',
  photo: '',
  fullName: '',
  email: '',
  phone: '',
  linkedin: '',
  github: '',
  website: '',
  jobTitle: '',
  experienceLevel: 'Mid Level',
  skills: '',
  experience: '',
  education: [],
  projects: '',
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [appState, setAppState] = useState<AppState>(AppState.EDITING);
  const [inputData, setInputData] = useState<UserInput>(initialInput);
  const [resumeData, setResumeData] = useState<GeneratedResume | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isGuest, setIsGuest] = useState(false);

  const handleLogin = (identifier: string, type: 'email' | 'phone') => {
    setIsAuthenticated(true);
    setIsGuest(false);
    // Pre-fill data based on login
    setInputData(prev => ({
      ...prev,
      [type]: identifier
    }));
  };

  const handleGuestLogin = () => {
    setIsAuthenticated(true);
    setIsGuest(true);
    setInputData(initialInput);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsGuest(false);
    setAppState(AppState.EDITING);
    setInputData(initialInput);
    setResumeData(null);
    setError(null);
  };

  const handleGenerate = async () => {
    setAppState(AppState.GENERATING);
    setError(null);
    try {
      const result = await generateResumeContent(inputData);
      setResumeData(result);
      setAppState(AppState.VIEWING);
    } catch (err) {
      console.error(err);
      setError("Failed to generate resume. Please ensure all fields contain valid information and try again.");
      setAppState(AppState.EDITING);
    }
  };

  const handleEdit = () => {
    setAppState(AppState.EDITING);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} onGuestLogin={handleGuestLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-100 print:bg-white">
      {/* Navbar - hidden on print */}
