                      </button>
                    </div>
                  ))}
                </div>
              )}

              {/* Add Education Form */}
              <div className={`bg-gray-50 p-4 rounded-lg border ${hasUnsavedEducation ? 'border-sky-300 ring-1 ring-sky-200' : 'border-gray-200'} space-y-3 transition-all`}>
