                  <div className="space-y-1">
                    <label className="text-xs text-gray-500 font-medium ml-1">End Year</label>
                    <select
                      value={newEdu.endYear}
                      onChange={(e) => setNewEdu(prev => ({ ...prev, endYear: e.target.value }))}
                      className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-1 focus:ring-sky-500 outline-none bg-white text-gray-900"
                    >
                       <option value="Present">Present</option>
                       {years.map(year => (
                         <option key={`end-${year}`} value={year}>{year}</option>
                       ))}
                    </select>
                  </div>
                </div>

                <button 
                  onClick={handleAddEducation}
                  disabled={!newEdu.degree || !newEdu.school}
                  className="w-full py-2 bg-sky-100 text-sky-700 font-medium rounded hover:bg-sky-200 transition-colors flex items-center justify-center gap-1 text-sm disabled:opacity-50 disabled:cursor-not-allowed mt-2"
